window.ScripturaLexicons.BDAG_PART_0132 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epaineo-bdag\" data-source=\"BDAG\" data-search=\"ἐπαινέω epainéō verbo louvar; elogiar; aprovar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπαινέω</td><td>verbo</td><td>louvar; elogiar; aprovar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epainos-bdag\" data-source=\"BDAG\" data-search=\"ἔπαινος, ου, ὁ épainos substantivo masculino louvor; elogio; reconhecimento; coisa louvável BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἔπαινος, ου, ὁ</td><td>substantivo masculino</td><td>louvor; elogio; reconhecimento; coisa louvável</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epairo-bdag\" data-source=\"BDAG\" data-search=\"ἐπαίρω epaírō verbo levantar; erguer; opor-se; ser presunçoso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπαίρω</td><td>verbo</td><td>levantar; erguer; opor-se; ser presunçoso</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epaischynomai-bdag\" data-source=\"BDAG\" data-search=\"ἐπαισχύνομαι epaischýnomai verbo médio envergonhar-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπαισχύνομαι</td><td>verbo médio</td><td>envergonhar-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epaiteo-bdag\" data-source=\"BDAG\" data-search=\"ἐπαιτέω epaitéō verbo mendigar; pedir esmola BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπαιτέω</td><td>verbo</td><td>mendigar; pedir esmola</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epakoloutheo-bdag\" data-source=\"BDAG\" data-search=\"ἐπακολουθέω epakolouthéō verbo seguir; suceder; dedicar-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπακολουθέω</td><td>verbo</td><td>seguir; suceder; dedicar-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epakouo-bdag\" data-source=\"BDAG\" data-search=\"ἐπακούω epakoúō verbo ouvir; atender; obedecer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπακούω</td><td>verbo</td><td>ouvir; atender; obedecer</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epakroaomai-bdag\" data-source=\"BDAG\" data-search=\"ἐπακροάομαι epakroáomai verbo médio escutar; ouvir sem ser notado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπακροάομαι</td><td>verbo médio</td><td>escutar; ouvir sem ser notado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epallelos-bdag\" data-source=\"BDAG\" data-search=\"ἐπάλληλος, ον epállēlos adjetivo sucessivo; repetido; consecutivo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπάλληλος, ον</td><td>adjetivo</td><td>sucessivo; repetido; consecutivo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epan-bdag\" data-source=\"BDAG\" data-search=\"ἐπάν epán conjunção temporal quando; assim que BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπάν</td><td>conjunção temporal</td><td>quando; assim que</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epanankes-bdag\" data-source=\"BDAG\" data-search=\"ἐπάναγκες epánankes advérbio; neutro necessariamente; coisa necessária BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπάναγκες</td><td>advérbio; neutro</td><td>necessariamente; coisa necessária</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epanago-bdag\" data-source=\"BDAG\" data-search=\"ἐπανάγω epanágō verbo fazer-se ao largo; retornar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπανάγω</td><td>verbo</td><td>fazer-se ao largo; retornar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epanakampto-bdag\" data-source=\"BDAG\" data-search=\"ἐπανακάμπτω epanakámptō verbo voltar; retornar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπανακάμπτω</td><td>verbo</td><td>voltar; retornar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epanamimnesko-bdag\" data-source=\"BDAG\" data-search=\"ἐπαναμιμνῄσκω epanamimnḗskō verbo lembrar novamente; fazer recordar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπαναμιμνῄσκω</td><td>verbo</td><td>lembrar novamente; fazer recordar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epanapauomai-bdag\" data-source=\"BDAG\" data-search=\"ἐπαναπαύομαι epanapaúomai verbo médio descansar; encontrar apoio; confiar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπαναπαύομαι</td><td>verbo médio</td><td>descansar; encontrar apoio; confiar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epanatrecho-bdag\" data-source=\"BDAG\" data-search=\"ἐπανατρέχω epanatréchō verbo correr; apressar-se para a meta BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπανατρέχω</td><td>verbo</td><td>correr; apressar-se para a meta</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epanerchomai-bdag\" data-source=\"BDAG\" data-search=\"ἐπανέρχομαι epanérchomai verbo médio voltar; retornar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπανέρχομαι</td><td>verbo médio</td><td>voltar; retornar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epaneko-bdag\" data-source=\"BDAG\" data-search=\"ἐπανήκω epanḗkō verbo voltar novamente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπανήκω</td><td>verbo</td><td>voltar novamente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epanistemi-bdag\" data-source=\"BDAG\" data-search=\"ἐπανίστημι epanístēmi verbo levantar-se; insurgir-se; rebelar-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπανίστημι</td><td>verbo</td><td>levantar-se; insurgir-se; rebelar-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epanorthosis-bdag\" data-source=\"BDAG\" data-search=\"ἐπανόρθωσις, εως, ἡ epanórthōsis substantivo feminino correção; restauração; aperfeiçoamento BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπανόρθωσις, εως, ἡ</td><td>substantivo feminino</td><td>correção; restauração; aperfeiçoamento</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article id=\"entry-epaineo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπαινέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epainéō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐπαινέω</span>; futuro <span class=\"greek\">ἐπαινέσω</span>; primeiro aoristo <span class=\"greek\">ἐπῄνεσα</span>; primeiro futuro passivo <span class=\"greek\">ἐπαινεσθήσομαι</span>, LXX (ver o verbete seguinte; Hom. e posteriores; inscrições [especialmente decretos honoríficos], papiros, LXX, EpArist; JosAs 24:11; Philo, Joseph., Test12Patr; Tat.; Ath. 15, 2): «expressar admiração ou aprovação por uma pessoa, objeto ou acontecimento; louvar, elogiar». <span class=\"greek\">τινά</span>, «alguém» (Jos., Vi. 232, <span class=\"greek\">ἐμέ</span>; 279; Tat.; Ath. 15, 2), 1Co 11:22a; IMg 12; ISm 5:2; MPol 4. <span class=\"greek\">ἑαυτὸν</span> <span class=\"greek\">ἐ</span>., «louvar-se a si mesmo», Hs 9, 22, 2. <span class=\"greek\">τὶ</span>, «alguma coisa» (Aelian, VH 2, 12; Jos., Ant. 14, 293, <span class=\"greek\">τ</span>. <span class=\"greek\">ἔργον</span>; Ar. 13, 7; Just., D. 2:5), 1Cl 33:6. Uso absoluto em 1Co 11:22b, a menos que se deva suprir <span class=\"greek\">ὑμᾶς</span>; cf. ibid., a. Com acusativo seguido de <span class=\"greek\">ὅτι</span>: «louvar alguém porque, ou pelo fato de que», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 16:8</a> (ver a bibliografia em <span class=\"greek\">οἰκονόμος</span> 1; JDerrett, NTS 7, 1960/61, 210, n. 3, «sanção»); <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.2\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 11:2</a>. <span class=\"greek\">τοῦτο</span> … <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐπαινῶ</span> <span class=\"greek\">ὅτι</span>, «isso é algo que não posso louvar [aprovar], a saber, que…», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.17\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 11:17</a> (para o sentido «aprovar»: Appian, Bell. Civ. 3, 14 §49; Ael. Aristid. 24, 22 K. = 44, p. 831 D.; Aelian, Fgm. 235, p. 263, 17, <span class=\"greek\">τὸ</span> <span class=\"greek\">θεῖον</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐπῄνει</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">βασιλέως</span> <span class=\"greek\">πραττόμενα</span>. Frequentemente em Philostrat. [Schmid IV 294]; Jos., Ant. 14, 293. Outros exemplos em AFridrichsen, Horae Soederblomianae I/1, 1944, 28–32. Sobre o contraste entre o que pode e o que não pode ser ordenado, cf. SIG 22, 10–26). Passivo: <span class=\"greek\">ἡ</span> <span class=\"greek\">γῆ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἰακὼβ</span> <span class=\"greek\">ἐπαινουμένη</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">πᾶσαν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">γῆν</span>, «a terra de Jacó, louvada acima de toda a terra», B 11:9 (citação de profeta desconhecido). Também no emprego religioso: «louvar a Deus» (Philo), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.11\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 15:11</a> (Sl 116:1, variante); GJs 8:1. — DELG, s.v. <span class=\"greek\">αἶνος</span>. M-M. TW.</p></section></article>\n<article id=\"entry-epainos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔπαινος, ου, ὁ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦épainos⟧</span><span class=\"separator\">·</span><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἔπαινος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (ver o verbete anterior; Simonides, Pind., Hdt. e posteriores).</p>\n<p class=\"entry-text\"><span class=\"sense-number\">①</span> O ato de expressar admiração ou aprovação: «louvor, elogio, aprovação, reconhecimento».</p>\n<p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> Dirigido a seres humanos (frequentemente em inscrições honoríficas).</p>\n<p class=\"entry-text\"><span class=\"greek\">α</span>. Proveniente de seres humanos: <span class=\"greek\">ἔκ</span> <span class=\"greek\">τινος</span>, 1Cl 30:6; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.29\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 2:29</a>; 13:3. <span class=\"greek\">εἰς</span> <span class=\"greek\">ἔπαινόν</span> <span class=\"greek\">τινος</span>, «para conceder reconhecimento a alguém», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 2:14</a> (WvanUnnik, NTS 2, 1955, 198–202, com referência a Diod S 15, 1, 1). <span class=\"greek\">ὁ</span> <span class=\"greek\">ἀδελφός</span>, <span class=\"greek\">οὗ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ἔ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">εὐαγγελίῳ</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">πασῶν</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἐκκλησιῶν</span>, «o irmão cuja fama em conexão com o evangelho se difundiu por todas as igrejas», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.18\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 8:18</a>.</p>\n<p class=\"entry-text\"><span class=\"greek\">β</span>. Proveniente de Deus (cf. Wsd 15:19; Just., D. 123, 4), 1Cl 30:6; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.29\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 2:29</a> (AFridrichsen, Symbolae Arctoae 1, 1922, 39–49). <span class=\"greek\">ὁ</span> <span class=\"greek\">ἔ</span>. <span class=\"greek\">γενήσεται</span> <span class=\"greek\">ἑκάστῳ</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεοῦ</span>, «cada um receberá louvor da parte de Deus», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.5\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 4:5</a> (sobre <span class=\"greek\">ἔ</span>. <span class=\"greek\">γίνεταί</span> <span class=\"greek\">τινι</span>, cf. SIG 304, 24). — <span class=\"greek\">εἰς</span> <span class=\"greek\">ἔ</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">δόξαν</span>, «para louvor e glória» (sobre a combinação dos dois substantivos, cf. IPriene 53, 15 [séc. II a.C.], <span class=\"greek\">ἀξίως</span> <span class=\"greek\">ἐπαίνου</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τιμῶν</span> <span class=\"greek\">ποιεῖσθαι</span> <span class=\"greek\">τ</span>. <span class=\"greek\">κρίσεις</span>; 199, 9 [séc. I a.C.]; Dio Chrys. 14 [31], 111, <span class=\"greek\">δόξα</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἔ</span>.; 1Cr 16:27; ver ⓑ abaixo), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 1:7</a> (com <span class=\"greek\">τιμή</span> e <span class=\"greek\">δόξα</span>; para o aspecto honorífico, cf. IPriene 53, 15, <span class=\"greek\">ἐ</span>. com <span class=\"greek\">τιμή</span>; 119, 9, <span class=\"greek\">ἐ</span>. com <span class=\"greek\">δόξα</span>).</p>\n<p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> Dirigido a Deus (cf. Sl 21:26; 34:28; Sir 39:10; concretamente, «cântico de louvor» em honra de Deus: Diod S 3, 73, 5; Arrian, Anab. 7, 3, 3, <span class=\"greek\">ἔπαινοι</span> <span class=\"greek\">θεῶν</span>): <span class=\"greek\">εἰς</span> <span class=\"greek\">δόξαν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἔ</span>. <span class=\"greek\">θεοῦ</span>, «para glória e louvor de Deus» (ver ⓐ<span class=\"greek\">β</span> acima), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 1:11</a>; cf. <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 1:6</a>, 12, 14.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">②</span> «Coisa digna de louvor» (Sir 39:10, <span class=\"greek\">ἔ</span>. <span class=\"greek\">αὐτοῦ</span> = «aquilo que nele é louvável / suas obras dignas de louvor»), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 4:8</a>. B. 1189. — DELG, s.v. <span class=\"greek\">αἶνος</span>. M-M. EDNT. TW. Sv.</p></section></article>\n<article id=\"entry-epairo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπαίρω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epaírō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐπαίρω</span> (ver <span class=\"greek\">αἴρω</span>); primeiro aoristo <span class=\"greek\">ἐπῆρα</span>, infinitivo <span class=\"greek\">ἐπᾶραι</span>, imperativo da segunda pessoa do singular <span class=\"greek\">ἔπαρον</span> (JosAs 17:6), particípio <span class=\"greek\">ἐπάρας</span>; perfeito <span class=\"greek\">ἐπῆρκα</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.18\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 13:18</a>, variante de leitura. Passivo: primeiro futuro <span class=\"greek\">ἐπαρθήσομαι</span>, LXX; primeiro aoristo <span class=\"greek\">ἐπήρθην</span>; particípio perfeito <span class=\"greek\">ἐπηρμένος</span>, LXX (autores trágicos, Hdt. e posteriores).</p>\n<p class=\"entry-text\"><span class=\"sense-number\">①</span> Fazer alguma coisa mover-se para cima: «levantar, erguer, manter erguido»; <span class=\"greek\">τὶ</span>, «alguma coisa»: <span class=\"greek\">ῥάβδον</span>, «uma vara» (Êx 10:13), Hv 3, 2, 4; <span class=\"greek\">τὸν</span> <span class=\"greek\">ἀρτέμωνα</span>, «a vela de proa», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.40\" target=\"_blank\" rel=\"noopener noreferrer\">At 27:40</a> (ver <span class=\"greek\">ἀρτέμων</span>). <span class=\"greek\">ἐπῆρεν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ποιμὴν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">χεῖρα</span> <span class=\"greek\">αὐτοῦ</span>, «o pastor ergueu a mão», GJs 8:3 (not pap., conforme abreviatura da fonte). Especialmente na expressão <span class=\"greek\">ἐ</span>. <span class=\"greek\">χεῖρας</span>, «erguer as mãos» em oração (Aesop, Fab. 49 P. = 83 H./74 Ch./49 H-H.; Horapollo 1, 15, <span class=\"greek\">τ</span>. <span class=\"greek\">χεῖρας</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">οὐρανὸν</span> <span class=\"greek\">ἐπαίροντα</span> … <span class=\"greek\">προσευχόμενος</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">θεῷ</span>; 2Esdr 18:6; Sl 133:2; sobre a ideia, cf. LvSybel, Christl. Antike I, 1906, 256; 258; GAppel, De Romanorum Precationibus, 1909, 194; cf. também <span class=\"greek\">ἐκτείνω</span> 1), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 2:8</a>; ou ao abençoar (Sir 50:20; JosAs 8:9, <span class=\"greek\">τὴν</span> <span class=\"greek\">χεῖρα</span>), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.50\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 24:50</a>. <span class=\"greek\">ἐ</span>. <span class=\"greek\">τὰς</span> <span class=\"greek\">κεφαλάς</span> (com <span class=\"greek\">ἀνακύπτειν</span>), «erguer as cabeças» (Philo, Op. M. 158; Jos., Bell. 1, 629; cf. <span class=\"greek\">ἐ</span>. <span class=\"greek\">τὸ</span> <span class=\"greek\">πρόσωπον</span>, 4Km 9:32; <span class=\"greek\">αὐχένα</span>, Philo, Fug. 107), de pessoas que recuperam a coragem, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.28\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 21:28</a>. <span class=\"greek\">ἐ</span>. <span class=\"greek\">τοὺς</span> <span class=\"greek\">ὀφθαλμούς</span> (Gn 13:10; 1Cr 21:16 e outros), «erguer os olhos, olhar para cima», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17:8</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 16:23</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.35\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 4:35</a>; 6:5; <span class=\"greek\">εἴς</span> <span class=\"greek\">τινα</span>, «para alguém», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.20\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 6:20</a>; <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">οὐρανόν</span>, «para o céu», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 18:13</a> (En 13:5, <span class=\"greek\">οὐκέτι</span> <span class=\"greek\">δύνανται</span> … <span class=\"greek\">ἐπᾶραι</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ὀφθ</span>. <span class=\"greek\">εἰς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">οὐρ</span>. <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">αἰσχύνης</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">ὧν</span> <span class=\"greek\">ἡμαρτήκεισαν</span>); <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.17.1\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 17:1</a>. <span class=\"greek\">ἐ</span>. <span class=\"greek\">τὴν</span> <span class=\"greek\">πτέρναν</span>, «erguer o calcanhar para pisar em alguém», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.18\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 13:18</a> (<span class=\"greek\">ἐπί</span> <span class=\"greek\">τινα</span> como em 1Km 20:33). <span class=\"greek\">ἐ</span>. <span class=\"greek\">τὴν</span> <span class=\"greek\">φωνήν</span>, «erguer a voz» (Demosth. 18, 291; Chariton 5, 7, 10; Philostrat., Vi. Apollon. 5, 33, p. 190, 21; Jz 2:4; 9:7; 2Km 13:36), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 11:27</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">At 2:14</a>; 14:11; 22:22. — Passivo: «ser elevado», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">At 1:9</a>. Da exaltação ao céu dos que perseveraram, 1Cl 45:8.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">②</span> «Oferecer resistência, opor-se, insurgir-se», extensão da acepção ① (cf., em sentido diferente, Just., A I, 58, 3, <span class=\"greek\">τῆς</span> <span class=\"greek\">γῆς</span>, «da terra»); <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινα</span> ou <span class=\"greek\">τι</span>, «contra alguém ou alguma coisa» (como 2Esdr 4:19; 1Macc 8:5; 10:70; TestJob 34:4, <span class=\"greek\">καθ</span>’ <span class=\"greek\">ἡμῶν</span>): <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ποίμνιον</span>, «contra o rebanho», 1Cl 16:1. <span class=\"greek\">κατά</span> <span class=\"greek\">τινος</span>: <span class=\"greek\">πᾶν</span> <span class=\"greek\">ὕψωμα</span> <span class=\"greek\">ἐπαιρόμενον</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">γνώσεως</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεοῦ</span>, «toda altivez que se levanta contra o conhecimento de Deus», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.5\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 10:5</a> (ver <span class=\"greek\">ὕψωμα</span> 2).</p>\n<p class=\"entry-text\"><span class=\"sense-number\">③</span> Insinuar que se é superior ao que realmente se é: «ser presunçoso, dar-se ares», uso absoluto (Aristoph., Nub. 810; Thu. 4, 18, 4; Aeschin. 87, 24; Sir 11:4; 32:1; 1Macc 2:63; Jos., Vi. 24), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.20\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 11:20</a>; 1Cl 21:5. Com <span class=\"greek\">ὑπερυψοῦσθαι</span>, 1Cl 14:5 (Sl 36:35). Com dativo para indicar o fundamento da presunção (Hdt. 9, 49; Thu. 1, 120, 3; X., Cyr. 8, 5, 24; Appian, Bell. Civ. 5, 118 §489, <span class=\"greek\">ταῖς</span> <span class=\"greek\">ναυσὶν</span> <span class=\"greek\">ἐπαιρόμενος</span> = «orgulhoso de sua frota»; Sf 1:11; Philo, Mos. 1, 70; Jos., Ant. 9, 193): <span class=\"greek\">ἑαυτοὺς</span> <span class=\"greek\">βουλόμενοι</span> <span class=\"greek\">ἐπαίρεσθαι</span> <span class=\"greek\">τ</span>. <span class=\"greek\">διανοίαις</span> <span class=\"greek\">αὐτῶν</span>, «desejando vangloriar-se de suas imaginações», 1Cl 39:1 (cf. Appian, Liby. 111 §522, <span class=\"greek\">ἐπήρθησαν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">φρονήμασι</span> = «tornaram-se presunçosos por confiarem em si mesmos»). — DELG, s.v. 1 <span class=\"greek\">ἀείρω</span>. M-M. TW.</p></section></article>\n<article id=\"entry-epaischynomai-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπαισχύνομαι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epaischýnomai⟧</span><span class=\"separator\">·</span><span>verbo médio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐπαισχύνομαι</span>; primeiro aoristo <span class=\"greek\">ἐπαισχύνθην</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">2Tm 1:16</a>; primeiro futuro <span class=\"greek\">ἐπαισχυνθήσομαι</span> (ver <span class=\"greek\">αἰσχύνη</span>; Aeschyl., Hdt. e outros; LXX; TestJos 2:5): «experimentar sentimento doloroso ou perda de prestígio devido a determinado acontecimento ou atividade; envergonhar-se».</p>\n<p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> Com acusativo de pessoa: «envergonhar-se de alguém» (X., Hell. 4, 1, 34; Lucian, Dem. 46b), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 8:38</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 9:26</a>; ISm 10:2b. Com acusativo de coisa (Pla., Soph. 247c; Diod S 1, 83, 4; Jó 34:19): <span class=\"greek\">τοὺς</span> <span class=\"greek\">λόγους</span>, «das palavras», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 8:38</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 9:26</a>; <span class=\"greek\">τὸ</span> <span class=\"greek\">εὐαγγέλιον</span>, «do evangelho», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 1:16</a> (OMichel, GWehrung Festschr. 1940, 36–53); <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄνομα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span>, «do nome do Senhor», Hs 8, 6, 4; 9, 21, 3; <span class=\"greek\">τὸ</span> <span class=\"greek\">μαρτύριον</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span> <span class=\"greek\">ἡμῶν</span>, «de dar testemunho de nosso Senhor», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">2Tm 1:8</a>; <span class=\"greek\">τὴν</span> <span class=\"greek\">ἅλυσίν</span> <span class=\"greek\">μου</span>, «de minhas cadeias», v. 16; cf. ISm 10:2 (com <span class=\"greek\">ὑπερηφανεῖν</span>).</p>\n<p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> Com <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινι</span>, referente a alguma coisa (Is 1:29; cf. Aristot., De Rhet. 2, 2): <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">οἷς</span> <span class=\"greek\">νῦν</span> <span class=\"greek\">ἐπαισχύνεσθε</span>, «das quais agora vos envergonhais», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.21\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 6:21</a>.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">ⓒ</span> Seguido de infinitivo (Aeschyl., Ag. 1373; Lucian, Dem. 46a): <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">ἀδελφοὺς</span> <span class=\"greek\">αὐτοὺς</span> <span class=\"greek\">καλεῖν</span>, «ele não se envergonha [isto é, não se considera superior demais] de chamá-los irmãos», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:11</a>; Hs 9, 14, 6. Com acusativo da pessoa e infinitivo, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.16\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:16</a>.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">ⓓ</span> Uso absoluto (Pla., Rep. 9, 573b; TestJos 2:5), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">2Tm 1:12</a>; GJs 17:1. — DELG, s.v. <span class=\"greek\">αἶσχος</span>. TW.</p></section></article>\n<article id=\"entry-epaiteo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπαιτέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epaitéō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐπαιτέω</span>; primeiro aoristo, imperativo da terceira pessoa do plural <span class=\"greek\">ἐπαιτησάτωσαν</span>, Sl 108:10 (Hom. e outros, no sentido de «pedir mais»; papiros, LXX): «mendigar, pedir esmola como mendigo» (assim Soph., O. C. 1364; Cat. Cod. Astr. VIII/4, p. 140, 9; Sl 108:10; Sir 40:28; Jos., Bell. 2, 295), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.3\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 16:3</a>; 18:35; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.46\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 10:46</a>, variante de leitura. — M-M.</p></section></article>\n<article id=\"entry-epakoloutheo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπακολουθέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epakolouthéō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐπακολουθέω</span>; futuro <span class=\"greek\">ἐπακολουθήσω</span>, LXX; primeiro aoristo <span class=\"greek\">ἐπηκολούθησα</span> (Aristoph., Thu. e posteriores; inscrições, papiros, LXX; TestNapht 3:3; Philo, Joseph.; Just., D. 65, 2, <span class=\"greek\">λόγους</span> <span class=\"greek\">ἐπακολουθοῦντας</span>; Ath., R. 78, 29).</p>\n<p class=\"entry-text\"><span class=\"sense-number\">①</span> Tomar alguém como modelo para fazer alguma coisa: «seguir»; <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἴχνεσιν</span> <span class=\"greek\">αὐτοῦ</span>, «seguir as pegadas [de Cristo]» (Philo, Virt. 64), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.21\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 2:21</a>. <span class=\"greek\">ἐπηκολούθησάν</span> <span class=\"greek\">μοι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">λόγον</span> <span class=\"greek\">θεοῦ</span>, «seguiram-me na causa de Deus», ISm 10:1 (cf. Philo, Leg. ad Gai. 185). A respeito dos profetas que seguiram Moisés no tempo, 1Cl 43:1.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">②</span> Ocorrer como resultado ou como acontecimento apropriado associado a alguma coisa: «seguir, suceder». Em contraste com <span class=\"greek\">προάγω</span>, Pol 3:3; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.24\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 5:24</a>. — <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐπακολουθοῦντα</span> <span class=\"greek\">σημεῖα</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 16:20</a>, não são apenas os sinais que seguem ou acompanham, mas também os que autenticam [a mensagem] (para esse significado de <span class=\"greek\">ἐ</span>., cf. PTebt 100, 20s [117/116 a.C.]; PEleph 10, 8 [223 a.C.]; PGen 22, 1).</p>\n<p class=\"entry-text\"><span class=\"sense-number\">③</span> Dedicar-se a alguma coisa com empenho fervoroso: «seguir, dedicar-se a alguma coisa», com dativo (cf. Pla., Rep. 2, 370c; Js 14:14, <span class=\"greek\">τῷ</span> <span class=\"greek\">προστάγματι</span> <span class=\"greek\">κυρίου</span>; Jos., C. Ap. 1, 6); <span class=\"greek\">παντὶ</span> <span class=\"greek\">ἔργῳ</span> <span class=\"greek\">ἀγαθῷ</span> <span class=\"greek\">ἐ</span>., «dedicar-se a toda boa obra», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 5:10</a>. — DELG, s.v. <span class=\"greek\">ἀκόλουθος</span>. M-M. TW.</p></section></article>\n<article id=\"entry-epakouo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπακούω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epakoúō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐπακούω</span>; futuro <span class=\"greek\">ἐπακούσομαι</span>; primeiro aoristo <span class=\"greek\">ἐπήκουσα</span>; perfeito, terceira pessoa do singular <span class=\"greek\">ἐπακήκοε</span>, LXX; infinitivo <span class=\"greek\">ἐπακηκοέναι</span> (Just., D. 137, 4); primeiro aoristo passivo, terceira pessoa do singular <span class=\"greek\">ἐπηκούσθη</span>, 2Cr 30:27 (ver <span class=\"greek\">ἀκούω</span>; Hom. [Il. 2, 143, no sentido de «ouvir falar de»] e posteriores; Tat. 30, 2, «entender» uma língua estrangeira). Sobre a LXX, ver JBarr, JTS 31, 1980, 67–72.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">①</span> Prestar cuidadosa atenção àquilo que se diz, com a implicação de reação favorável: «ouvir, escutar, dar ouvidos» (Aeschyl., Choëph. 725; Lucian, Tim. 34, <span class=\"greek\">τ</span>. <span class=\"greek\">εὐχῶν</span>; Mitt-Wilck. I/2, 478, 6 = BGU 1080, 6; IMaronIsis 7; PGM 13, 207, <span class=\"greek\">μοι</span>; LXX; <span class=\"greek\">τῆς</span> <span class=\"greek\">φωνῆς</span> <span class=\"greek\">ἡμῶν</span>, En 103:14; 106:8; Jos., Ant. 9, 10); <span class=\"greek\">τινός</span>, «de alguém» (Lucian, Pseudolog. 23; UPZ 78, 24 [159 a.C.], Isis, <span class=\"greek\">ἐπάκουσόν</span> <span class=\"greek\">μου</span>; PGM 3, 497; Gn 17:20 e outros; TestAbr A 14, p. 94, 2 [Stone p. 36]; JosAs 14:2), 1Cl 8:3 (citação de original desconhecido; cf. Is 65:24); B 3:5; <span class=\"greek\">ἐπήκουσά</span> <span class=\"greek\">σου</span>, «eu te ouvi», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.6.2\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 6:2</a> (Is 49:8; CCox, Biblica 62, 1981, 251–58); <span class=\"greek\">τῆς</span> <span class=\"greek\">δεήσεως</span>, «da súplica», GJs 2:4; 4:1s; 20:3 (not pap., conforme abreviatura da fonte); <span class=\"greek\">προσευχομένου</span> <span class=\"greek\">Ἰωνᾶ</span>, «de Jonas enquanto orava», AcPlCor 2:30. — OWeinreich, <span class=\"greek\">Θεοὶ</span> <span class=\"greek\">ἐπήκοοι</span>: MAI 37, 1912, 1–68.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">②</span> Agir apropriadamente em resposta ao que se ouviu: «atender, obedecer» (Hes., Op. 275; Hdt. 4, 141; Pla., Soph. 227c; Vett. Val. 67, 16; Jz 2:17 A; 1Macc 10:38, variante de leitura). Uso absoluto: <span class=\"greek\">πρέπον</span> <span class=\"greek\">ἐστὶν</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">κατὰ</span> <span class=\"greek\">μηδεμίαν</span> <span class=\"greek\">ὑπόκρισιν</span>, «convém obedecer sem nenhuma hipocrisia», IMg 3:2. <span class=\"greek\">ἔμπροσθέν</span> <span class=\"greek\">τινος</span>, «diante de alguém» = «obedecer a alguém», B 12:11 (Is 45:1). — New Docs 1, 15. M-M. TW. Spicq. Sv.</p></section></article>\n<article id=\"entry-epakroaomai-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπακροάομαι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epakroáomai⟧</span><span class=\"separator\">·</span><span>verbo médio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐπακροάομαι</span>; imperfeito <span class=\"greek\">ἐπηκροώμην</span> (Menand., Epitr. 934 S. [614 Kö.]; Plato Com. [séculos V/IV a.C.], Fgm. 16 e outros; Hobart 234 [Hippocr.]): «escutar»; <span class=\"greek\">τινός</span>, «alguém» (Lucian, Icar. 1; Philostrat., Vi. Apoll. 4, 36, p. 154, 13; TestJos 8:5); no sentido de «ouvir sem ser notado, escutar de passagem», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.25\" target=\"_blank\" rel=\"noopener noreferrer\">At 16:25</a>. — DELG, s.v. <span class=\"greek\">ἀκούω</span>. M-M.</p></section></article>\n<article id=\"entry-epallelos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπάλληλος, ον</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epállēlos⟧</span><span class=\"separator\">·</span><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐπάλληλος</span>, <span class=\"greek\">ον</span>: relativo a alguma coisa que acontece repetidamente, em rápida sucessão (Polyb., Diod S, Plut. e outros; PFamTebt 15, 68 e 90), especialmente desgraças (Plut., Pomp. 632 [25, 10]; Philo, Mos. 2, 263; In Flacc. 121, <span class=\"greek\">τὰς</span> <span class=\"greek\">συνεχεῖς</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἐπαλλήλους</span> <span class=\"greek\">κακώσεις</span>; Jos., Bell. 5, 32): «que acontece repetidamente, sucessivo». <span class=\"greek\">ἐ</span>. <span class=\"greek\">γενόμεναι</span> <span class=\"greek\">συμφοραί</span>, «desgraças que ocorreram uma após outra», 1Cl 1:1. — DELG, s.v. <span class=\"greek\">ἄλλος</span>.</p></section></article>\n<article id=\"entry-epan-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπάν</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epán⟧</span><span class=\"separator\">·</span><span>conjunção temporal</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐπάν</span>, conjunção temporal empregada com subjuntivo (X. e outros; inscrições, papiros; Bel 11. Na forma <span class=\"greek\">ἐπήν</span> em Hom. e outros; LXX; Just., D. 69, 3): «quando, assim que». Com subjuntivo presente: <span class=\"greek\">ἐ</span>. <span class=\"greek\">πονηρὸς</span> <span class=\"greek\">ᾖ</span>, «quando estiver defeituoso», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 11:34</a>. Com subjuntivo aoristo, como o futuro perfeito latino (Jos., Ant. 8, 302): <span class=\"greek\">ἐ</span>. <span class=\"greek\">εὕρητε</span>, «quando o tiverdes encontrado», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:8</a>. <span class=\"greek\">ἐ</span>. <span class=\"greek\">νικήσῃ</span> <span class=\"greek\">αὐτόν</span>, literalmente «quando o tiver vencido», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 11:22</a>. — M-M.</p></section></article>\n<article id=\"entry-epanankes-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπάναγκες</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epánankes⟧</span><span class=\"separator\">·</span><span>advérbio; neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐπάναγκες</span> (ver <span class=\"greek\">ἀνάγκη</span>), neutro de <span class=\"greek\">ἐπανάγκης</span>, que ocorre apenas no neutro («obrigatório», Andoc. 1, 12; Pla., Leg. 878e e outros) e, na literatura considerada, somente como advérbio (Hdt. e outros; Epict. 2, 20, 1; M. Ant. 1, 16, 8; inscrições, papiros; Jos., Ant. 16, 365): relacionado ao que é essencial em determinada situação, «necessário, de natureza necessária». <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐπάναγκες</span>, «as coisas necessárias» = «aquilo que necessariamente [deve ser imposto]», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.28\" target=\"_blank\" rel=\"noopener noreferrer\">At 15:28</a>. — DELG, s.v. <span class=\"greek\">ἀνάγκη</span>. M-M.</p></section></article>\n<article id=\"entry-epanago-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπανάγω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epanágō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐπανάγω</span> (ver <span class=\"greek\">ἀνάγω</span>); aoristo <span class=\"greek\">ἐπανήγαγον</span>; particípio passivo <span class=\"greek\">ἐπαναχθέντας</span>, 2Macc 12:4 (<span class=\"greek\">ἀχθέντας</span>, códice A) (Hdt. e outros; inscrições, papiros, LXX, EpArist; Jos., Ant. 12, 128; 345). «Conduzir, levar para cima»; na literatura aqui considerada, somente intransitivo.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">①</span> Sair da costa para alcançar águas abertas: «partir, fazer-se ao largo». <span class=\"greek\">ἠρώτησεν</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">γῆς</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">ὀλίγον</span>, «pediu-lhe que afastasse um pouco [o barco] da margem», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 5:3</a> (transitivo = «lançar ao mar» navios e homens, X., Hell. 6, 2, 28, <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">γῆς</span>; 2Macc 12:4). <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">βάθος</span>, «para águas profundas», v. 4.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">②</span> Voltar para algum ponto ou área: «retornar» (X., Cyr. 4, 1, 3; Diod S 16, 26 e outros; 2Macc 9:21); <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">πόλιν</span>, «à cidade», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:18</a>. — M-M.</p></section></article>\n<article id=\"entry-epanakampto-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπανακάμπτω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epanakámptō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐπανακάμπτω</span>; primeiro aoristo <span class=\"greek\">ἐπανέκαμψα</span> (Aristot.; Aq., Sym., Theod., Is 35:10): «voltar a um lugar ou pessoa, retornar» (Syntipas, p. 14, 8 e outros); <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">πόλιν</span>, «à cidade», Hs 1:2, 5; <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">παρθένους</span>, «às virgens», Hs 9, 14, 1. — DELG, s.v. <span class=\"greek\">κάμπτω</span>.</p></section></article>\n<article id=\"entry-epanamimnesko-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπαναμιμνῄσκω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epanamimnḗskō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐπαναμιμνῄσκω</span> (também -<span class=\"greek\">ήσκω</span>); primeiro aoristo passivo <span class=\"greek\">ἐπανεμνήσθην</span>: «fazer alguém recordar novamente alguma coisa, lembrar [<span class=\"greek\">τινά</span>] de algo» (Pla., Leg. 3, 688a; Demosth. 6, 35), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.15\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 15:15</a>. Passivo: «trazer de novo à memória, lembrar-se novamente de alguma coisa»; <span class=\"greek\">τοῦ</span> <span class=\"greek\">ῥήματος</span>, «da palavra», Hv 4, 1, 7. — DELG, s.v. <span class=\"greek\">μιμνήσκω</span>.</p></section></article>\n<article id=\"entry-epanapauomai-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπαναπαύομαι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epanapaúomai⟧</span><span class=\"separator\">·</span><span>verbo médio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐπαναπαύομαι</span> (encontra-se na voz ativa em Aelian, NA 5, 56, e Jz 16:26 A; a voz média ocorre em Hero Alex. I, p. 424, 12; Epict.; Artem.; Herodian 2, 1, 2; Jos., Ant. 8, 84; quase sempre na LXX; uma vez em TestSol 7:7 P; e sem exceção na literatura aqui considerada); futuro <span class=\"greek\">ἐπαναπαύσομαι</span>; primeiro aoristo <span class=\"greek\">ἐπανεπαυσάμην</span>, LXX; perfeito, terceira pessoa do singular <span class=\"greek\">ἐπαναπέπαυται</span>, 4Km 2:15; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.14\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 4:14</a>, variante de leitura. Passivo: segundo futuro, terceira pessoa do singular <span class=\"greek\">ἐπαναπαήσεται</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 10:6</a> (-<span class=\"greek\">παύσεται</span>, variante); segundo aoristo <span class=\"greek\">ἐπανεπάην</span>, D 4:2.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">①</span> Estar em estado ou condição de repouso: «descansar, repousar»; GHb 70, 18 = Ox 654, 8s (mas este último texto encontra-se em estado fragmentário; ver nota do editor); B 4:13. Com a implicação de benefícios concedidos nesse processo: <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινα</span>, «repousar sobre alguém»; <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">εἰρήνη</span> <span class=\"greek\">ὑμῶν</span>, «vossa paz repousará sobre ele», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 10:6</a> (Nm 11:25, 26, <span class=\"greek\">ἐπανεπαύσατο</span> <span class=\"greek\">τ</span>. <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">αὐτούς</span>; 4Km 2:15; cf. <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.14\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 4:14</a>, variante).</p>\n<p class=\"entry-text\"><span class=\"sense-number\">②</span> Encontrar bem-estar ou segurança interior: «encontrar descanso, conforto, apoio»; <span class=\"greek\">τινί</span>, «em alguma coisa», e <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινα</span>, «sobre alguém», em sentido figurado (LXX; Herm. Wr. 9, 10, <span class=\"greek\">τῇ</span> <span class=\"greek\">πίστει</span> <span class=\"greek\">ἐ</span>.), <span class=\"greek\">τοῖς</span> <span class=\"greek\">λόγοις</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἁγίων</span>, «nas palavras dos santos», D 4:2; <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">πένητα</span>, «sobre o pobre», Hs 1, 2, 5 (ver <span class=\"greek\">ἀναπαύω</span>). No sentido «apoiar-se, confiar» (Trypho Gr. 194 [séc. I a.C.]; Artem. 4, 65; Epict. 1, 9, 9; Mq 3:11; 1Macc 8:11): <span class=\"greek\">νόμῳ</span>, «na Lei», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 2:17</a>. — M-M. TW.</p></section></article>\n<article id=\"entry-epanatrecho-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπανατρέχω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epanatréchō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐπανατρέχω</span> (<span class=\"greek\">ἀνατρέχω</span>, «correr de volta»); segundo aoristo <span class=\"greek\">ἐπανέδραμον</span> (Philod., De Ira, p. 63 W.; Lucian, Merc. Cond. 36; PLond III, 1044, 14, p. 254 [séc. VI d.C.]; V, 1727, 46; Jos., Ant. 18, 361): «correr em direção a alguma coisa, disputar uma corrida», em imagem de um corredor que faz a curva da pista e segue para a meta, mas provavelmente sem que se devam explorar os detalhes da imagem: «correr, apressar-se». <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">σκοπόν</span>, «em direção à meta», 1Cl 19:2 («correr novamente para a meta»; ver UWickert, ZNW 49, 1958, 270–75; recurramus no códice Namurc.).</p></section></article>\n<article id=\"entry-epanerchomai-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπανέρχομαι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epanérchomai⟧</span><span class=\"separator\">·</span><span>verbo médio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐπανέρχομαι</span> (ver <span class=\"greek\">ἀνέρχομαι</span>); futuro <span class=\"greek\">ἐπανελεύσομαι</span>, LXX; segundo aoristo <span class=\"greek\">ἐπανῆλθον</span>; perfeito <span class=\"greek\">ἐπανελήλυθεν</span> (Just., D. 56, 8) (Eur., Hdt. e outros): «voltar a um ponto ou região, retornar» (assim Thu., X., Pla.; SIG 591, 7 [c. 195 a.C.]; PLond III, 904, 23s, p. 125 [104 d.C.]; POxy 933, 17; PTebt 333, 10; Pv 3:28; 2Macc 4:36; Jos., Bell. 7, 106; Ant. 1, 91; Just., D. 56, 6 e outros; 56:1, <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">γραφὰς</span> <span class=\"greek\">ἐπανελθών</span>, «voltando às Escrituras»). Uso absoluto: <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ἐπανέρχεσθαί</span> <span class=\"greek\">με</span>, «quando eu voltar», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 10:35</a>; cf. 19:15; Hs 8, 2, 9. — M-M.</p></section></article>\n<article id=\"entry-epaneko-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπανήκω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epanḗkō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐπανήκω</span> (<span class=\"greek\">ἀνήκω</span>, «ter chegado a determinado ponto»); futuro <span class=\"greek\">ἐπανήξω</span>: «voltar novamente» (desde Eur., Iph. A. 1628; também Polyb. 6, 58, 3; SIG 730, 6; PAmh 50, 5; Sb 9123, 4 [ambos do séc. II a.C.]; PGron 18, 8; LXX; EpArist 8; Jos., Ant. 12, 179; 191), Hs 9, 11, 2.</p></section></article>\n<article id=\"entry-epanistemi-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπανίστημι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epanístēmi⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐπανίστημι</span> (ver <span class=\"greek\">ἀνίστημι</span>), «levantar, fazer surgir»; futuro médio <span class=\"greek\">ἐπαναστήσομαι</span>. Também particípio do primeiro aoristo ativo <span class=\"greek\">ἐπαναστήσας</span> (Mel., P. 82, 609, conjectura de Bonner); segundo aoristo ativo <span class=\"greek\">ἐπανέστην</span>; particípio perfeito <span class=\"greek\">ἐπανεστηκότων</span>, Dt 33:11: «tornar-se ativo em resistência enérgica ou manifestação de hostilidade; levantar-se, rebelar-se» (assim desde Il. 2, 85; Hdt., Thu., Aristoph., LXX, TestJob; ApcEsdr 3:13, p. 27, 25 Tdf.; ApcMos 24; Philo, Spec. Leg. 3, 17; SibOr 11, 175; PHib 249, 5; Sb 9302, 7 [ambos do séc. III a.C.]; Tat. 7, 2; Ath. 21, 3; Mel., Fgm. 5). <span class=\"greek\">τινί</span>, «contra alguém» (assim Hdt., Thu. e outros; Dt 33:11; Jdth 5:11; 16:17; PsSol; Jos., Bell. 1, 24; 2, 443; Tat., Ath.): <span class=\"greek\">ἐπανέστησάν</span> <span class=\"greek\">μοι</span>, «levantaram-se contra mim», B 5:13 (Sl 26:12). Também <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινα</span> (LXX), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:21</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 13:12</a> (cf. Mq 7:6). — M-M.</p></section></article>\n<article id=\"entry-epanorthosis-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπανόρθωσις, εως, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epanórthōsis⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐπανόρθωσις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span>: «correção, restauração» (cf., por exemplo, ISardGauthier 3, 1, «restauração» de uma cidade; 1Esdr 8:52; 1Macc 14:34), depois, em sentido transferido, «aperfeiçoamento, melhoria» (Ps.-Pla., Tim. L. 104a; Heraclid. Lembus, Pol. 14 [Aristot., Fgm. 611, 14 Rose]; Plut., Mor. 22a; 46d e outros. — <span class=\"greek\">ἐ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">βίου</span>: Polyb. 1, 35, 1; cf. o verbo <span class=\"greek\">ἐπανορθόω</span> em Strabo 9, 1, 20; Epict. 3, 21, 15, <span class=\"greek\">οὕτως</span> <span class=\"greek\">ὠφέλιμα</span> <span class=\"greek\">γίνεται</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">μυστήρια</span> … , <span class=\"greek\">ὅτι</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">ἐπανορθώσει</span> <span class=\"greek\">τ</span>. <span class=\"greek\">βίου</span> <span class=\"greek\">κατεστάθη</span> <span class=\"greek\">πάντα</span> … ; cf. Enchir. 51, 1; Iambl., Vi. Pyth. 6, 30; 21, 96, <span class=\"greek\">πρὸς</span> <span class=\"greek\">ἐ</span>.; POxy 78, 29; 237 VIII, 30; EpArist 130; 283, <span class=\"greek\">πρὸς</span> <span class=\"greek\">ἐ</span>.; Philo, Ebr. 91, <span class=\"greek\">πρὸς</span> <span class=\"greek\">ἐ</span>.; Conf. Lingu. 182; Leg. All. 1, 85; cf. 2Macc 2:22). <span class=\"greek\">ὠφέλιμος</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">ἐ</span>., «útil para o aperfeiçoamento», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">2Tm 3:16</a>. — B. 751. New Docs 2, 84. DELG, s.v. <span class=\"greek\">ὀρθός</span>. TW. Spicq.</p></section></article>"};
